import React, { useState } from "react";

export default function TextForm(props) {
  const [text, setText] = useState(" ");

  const handleUpClick = () => {
    // console.log("Up button clicked" + text);
    let newText = text.toUpperCase();
    setText(newText);
    props.showAlert("Converted to Uppercase", "success");
  };

  const handleLoClick = () => {
    // console.log("Up button clicked" + text);
    let newText = text.toLowerCase();
    setText(newText);
    props.showAlert("Converted to Lowercase", "success");
  };
  const handleClearClick = () => {
    // console.log("Up button clicked" + text);
    let newText = "";
    setText(newText);
    props.showAlert("Text Cleared", "success");
  };

  const handleOnChange = (event) => {
    // console.log("On change");
    setText(event.target.value);
  };
  const handleSpaces = (event) => {
    // console.log("On change");
    let newText = text.split(/[ ]+ /);
    setText(newText.join(" "));
    props.showAlert("Removed the Extra spaces from the TextBox", "success");
  };

  const handleCopy = (event) => {
    // console.log("On change");
    console.log("I am Copy");
    var text = document.getElementById("myBox");
    text.select();
    text.setSelectionRange(0, 9999);
    navigator.clipboard.writeText(text.value);
    props.showAlert("Text copied Successfully", "success");
  };

  return (
    <>
      <div
        className="container"
        style={{
          color: props.mode === "dark" ? "white" : "black",
          transition: "all 0.3s ease",
        }}
      >
        <h1>{props.heading}</h1>
        <div className="mb-3">
          <textarea
            className="form-control"
            value={text}
            id="myBox"
            rows="8"
            onChange={handleOnChange}
            style={{
              backgroundColor: props.mode === "dark" ? "grey" : "white",
              color: props.mode === "dark" ? "white" : "black",
              transition: "all 0.3s ease",
            }}
          ></textarea>
          <br />
          <button className="btn btn-primary mx-2" onClick={handleUpClick}>
            Convert to uppercase
          </button>

          <button className="btn btn-primary mx-2 my-3" onClick={handleLoClick}>
            Convert to lowercase
          </button>

          <button
            className="btn btn-primary mx-2 my-3"
            onClick={handleClearClick}
          >
            Clear Text
          </button>
          <button className="btn btn-primary mx-2 my-3" onClick={handleCopy}>
            Copy Text
          </button>
          <button className="btn btn-primary mx-2 my-3" onClick={handleSpaces}>
            Remove extra spaces
          </button>
        </div>
      </div>
      <div
        className="container my-3"
        style={{
          color: props.mode === "dark" ? "white" : "black",
          transition: "all 0.3s ease",
        }}
      >
        <h1>Your Text summary</h1>
        <p>
          {text.split(" ").filter((element) => element.length !== 0).length}{" "}
          words and {text.length} characters
        </p>
        <p>
          Estimated reading time:{" "}
          {0.008 *
            text.split(" ").filter((element) => element.length !== 0)
              .length}{" "}
          minutes
        </p>
        <h2>Preview</h2>
        <p>{text}</p>
      </div>
    </>
  );
}
